import client from './client'

export interface DramaSummary {
  id: number
  title: string
  description: string
  category: string
  coverUrl: string
  likeCount: number
  status: string
  episodeCount: number
}

export interface EpisodeSummary {
  id: number
  episodeNo: number
  title: string
  videoUrl: string
  durationSec: number
}

export interface DramaDetail extends DramaSummary {
  episodes: EpisodeSummary[]
  liked: boolean
  favorited: boolean
}

export function listDramas(): Promise<DramaSummary[]> {
  return client.get<DramaSummary[]>('/api/dramas').then((res) => res.data)
}

/** 详情：带 token 时 liked/favorited 反映当前用户真实状态，匿名恒 false。 */
export function getDrama(id: number | string): Promise<DramaDetail> {
  return client.get<DramaDetail>(`/api/dramas/${id}`).then((res) => res.data)
}

export function listEpisodes(id: number | string): Promise<EpisodeSummary[]> {
  return client.get<EpisodeSummary[]>(`/api/dramas/${id}/episodes`).then((res) => res.data)
}

export function formatLikes(count: number): string {
  return count >= 10000 ? `${(count / 10000).toFixed(1)}万` : count.toLocaleString()
}

import { createContext, useContext, useEffect, useState, type ReactNode } from 'react'
import { getMe, type UserInfo } from '../api/auth'
import { TOKEN_KEY } from '../api/client'

interface AuthContextValue {
  user: UserInfo | null
  token: string | null
  /** 初始化完成标记：挂载时校验 localStorage token 期间为 false，避免闪烁。 */
  ready: boolean
  login: (token: string, user: UserInfo) => void
  logout: () => void
}

const AuthContext = createContext<AuthContextValue | null>(null)

export function AuthProvider({ children }: { children: ReactNode }) {
  const [user, setUser] = useState<UserInfo | null>(null)
  const [token, setToken] = useState<string | null>(() => localStorage.getItem(TOKEN_KEY))
  const [ready, setReady] = useState(false)

  useEffect(() => {
    const stored = localStorage.getItem(TOKEN_KEY)
    if (!stored) {
      setReady(true)
      return
    }
    getMe()
      .then(setUser)
      .catch(() => {
        // token 过期/伪造：清掉，降级为访客，不打断当前页
        localStorage.removeItem(TOKEN_KEY)
        setToken(null)
      })
      .finally(() => setReady(true))
  }, [])

  const login = (newToken: string, newUser: UserInfo) => {
    localStorage.setItem(TOKEN_KEY, newToken)
    setToken(newToken)
    setUser(newUser)
  }

  const logout = () => {
    localStorage.removeItem(TOKEN_KEY)
    setToken(null)
    setUser(null)
  }

  return (
    <AuthContext.Provider value={{ user, token, ready, login, logout }}>
      {children}
    </AuthContext.Provider>
  )
}

export function useAuth(): AuthContextValue {
  const ctx = useContext(AuthContext)
  if (!ctx) {
    throw new Error('useAuth 必须在 AuthProvider 内使用')
  }
  return ctx
}

import { Navigate, useLocation } from 'react-router-dom'
import type { ReactNode } from 'react'
import { useAuth } from '../store/AuthContext'

/**
 * 整页登录守卫（备好供里程碑 4「我的收藏」等页面使用）。
 * 本阶段点赞/收藏按钮采用「点击时判断」而非整页守卫，故暂无路由挂载。
 */
export default function RequireAuth({ children }: { children: ReactNode }) {
  const { user, ready } = useAuth()
  const location = useLocation()

  if (!ready) {
    return null
  }
  if (!user) {
    const from = encodeURIComponent(location.pathname + location.search)
    return <Navigate to={`/login?from=${from}`} replace />
  }
  return children
}

import { useCallback, useEffect, useState } from 'react'
import { useNavigate } from 'react-router-dom'
import { useAuth } from '../store/AuthContext'

/**
 * 阶段2 点赞/收藏交互：仅 UI 状态回显 + 未登录引导登录，不写库（写库属里程碑 4）。
 * 返回的 like/favorite 供详情页与播放页共用。
 */
export function useDramaInteractions() {
  const { user } = useAuth()
  const navigate = useNavigate()
  const [hint, setHint] = useState('')

  useEffect(() => {
    if (!hint) {
      return
    }
    const timer = setTimeout(() => setHint(''), 2500)
    return () => clearTimeout(timer)
  }, [hint])

  const guarded = useCallback(
    (message: string) => {
      if (!user) {
        const from = encodeURIComponent(window.location.pathname + window.location.search)
        navigate(`/login?from=${from}`)
        return
      }
      setHint(message)
    },
    [user, navigate],
  )

  const like = useCallback(() => guarded('点赞功能即将上线，敬请期待'), [guarded])
  const favorite = useCallback(() => guarded('收藏功能即将上线，敬请期待'), [guarded])

  return { like, favorite, hint }
}

import { useEffect, useMemo, useState } from 'react'
import { Link } from 'react-router-dom'
import { getApiErrorMessage } from '../api/client'
import { formatLikes, listDramas, type DramaSummary } from '../api/dramas'

type LoadState = 'loading' | 'ready' | 'error'

export default function HomePage() {
  const [dramas, setDramas] = useState<DramaSummary[]>([])
  const [state, setState] = useState<LoadState>('loading')
  const [error, setError] = useState('')
  const [category, setCategory] = useState('全部')
  const [reloadKey, setReloadKey] = useState(0)

  useEffect(() => {
    let cancelled = false
    setState('loading')
    listDramas()
      .then((data) => {
        if (cancelled) return
        setDramas(data)
        setState('ready')
      })
      .catch((err) => {
        if (cancelled) return
        setError(getApiErrorMessage(err))
        setState('error')
      })
    return () => {
      cancelled = true
    }
  }, [reloadKey])

  // 分类条随种子数据生成（全部 + 去重分类），数据量小走前端过滤
  const categories = useMemo(
    () => ['全部', ...Array.from(new Set(dramas.map((drama) => drama.category)))],
    [dramas],
  )
  const visible = category === '全部' ? dramas : dramas.filter((drama) => drama.category === category)

  return (
    <main className="mx-auto w-full max-w-6xl px-4 py-5">
      {state === 'loading' && <p className="py-20 text-center text-sm text-neutral-400">加载中…</p>}

      {state === 'error' && (
        <div className="py-20 text-center">
          <p className="text-sm text-red-400">{error}</p>
          <button
            onClick={() => setReloadKey((key) => key + 1)}
            className="mt-3 rounded-lg border border-neutral-700 px-4 py-1.5 text-sm text-neutral-300 transition hover:border-neutral-500 hover:text-white"
          >
            重试
          </button>
        </div>
      )}

      {state === 'ready' && (
        <>
          <nav className="mb-4 flex gap-2 overflow-x-auto pb-1" aria-label="分类筛选">
            {categories.map((item) => (
              <button
                key={item}
                onClick={() => setCategory(item)}
                className={`shrink-0 rounded-full px-3.5 py-1.5 text-sm transition ${
                  item === category
                    ? 'bg-rose-500 font-medium text-white'
                    : 'border border-neutral-700 bg-neutral-900 text-neutral-300 hover:border-neutral-500 hover:text-white'
                }`}
              >
                {item}
              </button>
            ))}
          </nav>

          {visible.length === 0 ? (
            <p className="py-20 text-center text-sm text-neutral-400">该分类暂无短剧</p>
          ) : (
            <div className="grid grid-cols-2 gap-3 md:grid-cols-4 xl:grid-cols-6">
              {visible.map((drama) => (
                <Link
                  key={drama.id}
                  to={`/drama/${drama.id}`}
                  className="group overflow-hidden rounded-xl bg-neutral-900 transition hover:ring-1 hover:ring-rose-500/60"
                >
                  <div className="relative aspect-[9/16]">
                    <img
                      src={drama.coverUrl}
                      alt={drama.title}
                      loading="lazy"
                      className="h-full w-full object-cover transition group-hover:scale-105"
                    />
                    <span className="absolute left-1.5 top-1.5 rounded-md bg-black/55 px-1.5 py-0.5 text-xs">
                      {drama.category}
                    </span>
                    <span className="absolute bottom-1.5 right-1.5 rounded-md bg-black/55 px-1.5 py-0.5 text-xs text-rose-300">
                      ♥ {formatLikes(drama.likeCount)}
                    </span>
                  </div>
                  <div className="p-2">
                    <h2 className="truncate text-sm font-medium" title={drama.title}>
                      {drama.title}
                    </h2>
                    <p className="mt-0.5 text-xs text-neutral-400">全 {drama.episodeCount} 集</p>
                  </div>
                </Link>
              ))}
            </div>
          )}
        </>
      )}
    </main>
  )
}

import { useEffect, useState } from 'react'
import { Link, useParams } from 'react-router-dom'
import { getApiErrorMessage } from '../api/client'
import { formatLikes, getDrama, type DramaDetail } from '../api/dramas'
import { useDramaInteractions } from '../hooks/useDramaInteractions'

type LoadState = 'loading' | 'ready' | 'error'

export default function DramaDetailPage() {
  const { id } = useParams()
  const [detail, setDetail] = useState<DramaDetail | null>(null)
  const [state, setState] = useState<LoadState>('loading')
  const [error, setError] = useState('')
  const { like, favorite, hint } = useDramaInteractions()

  useEffect(() => {
    if (!id) {
      return
    }
    let cancelled = false
    setState('loading')
    getDrama(id)
      .then((data) => {
        if (cancelled) return
        setDetail(data)
        setState('ready')
      })
      .catch((err) => {
        if (cancelled) return
        setError(getApiErrorMessage(err))
        setState('error')
      })
    return () => {
      cancelled = true
    }
  }, [id])

  return (
    <main className="mx-auto w-full max-w-5xl px-4 py-6">
      {state === 'loading' && <p className="py-20 text-center text-sm text-neutral-400">加载中…</p>}

      {state === 'error' && (
        <div className="py-20 text-center">
          <p className="text-sm text-red-400">{error}</p>
          <Link
            to="/"
            className="mt-3 inline-block rounded-lg border border-neutral-700 px-4 py-1.5 text-sm text-neutral-300 transition hover:border-neutral-500 hover:text-white"
          >
            回首页
          </Link>
        </div>
      )}

      {state === 'ready' && detail && (
        <div className="flex flex-col gap-6 md:flex-row">
          <div className="mx-auto w-44 shrink-0 md:mx-0 md:w-52">
            <img
              src={detail.coverUrl}
              alt={detail.title}
              className="aspect-[9/16] w-full rounded-xl object-cover"
            />
          </div>

          <section className="min-w-0 flex-1">
            <h1 className="text-2xl font-bold">{detail.title}</h1>
            <div className="mt-2 flex flex-wrap items-center gap-2 text-sm text-neutral-400">
              <span className="rounded-full bg-rose-500/15 px-2 py-0.5 text-rose-400">{detail.category}</span>
              <span>全 {detail.episodeCount} 集</span>
              <span className="text-rose-300">♥ {formatLikes(detail.likeCount)}</span>
            </div>
            <p className="mt-4 text-sm leading-6 text-neutral-300">{detail.description}</p>

            <div className="mt-5 flex items-center gap-3">
              <button
                onClick={like}
                className={
                  detail.liked
                    ? 'rounded-lg bg-rose-500 px-5 py-2 text-sm font-medium text-white transition hover:bg-rose-600'
                    : 'rounded-lg border border-neutral-700 px-5 py-2 text-sm text-neutral-200 transition hover:border-rose-500 hover:text-rose-300'
                }
              >
                ♥ {detail.liked ? '已赞' : '点赞'}
              </button>
              <button
                onClick={favorite}
                className={
                  detail.favorited
                    ? 'rounded-lg bg-amber-500 px-5 py-2 text-sm font-medium text-white transition hover:bg-amber-600'
                    : 'rounded-lg border border-neutral-700 px-5 py-2 text-sm text-neutral-200 transition hover:border-amber-500 hover:text-amber-300'
                }
              >
                ★ {detail.favorited ? '已收藏' : '收藏'}
