            </div>
            {hint && <p className="mt-2 text-sm text-neutral-400">{hint}</p>}

            <h2 className="mt-8 text-base font-semibold">选集（共 {detail.episodeCount} 集）</h2>
            <div className="mt-3 grid grid-cols-4 gap-2 sm:grid-cols-6 md:grid-cols-8">
              {detail.episodes.map((episode) => (
                <Link
                  key={episode.id}
                  to={`/drama/${detail.id}/play?ep=${episode.episodeNo}`}
                  title={episode.title}
                  className="rounded-lg border border-neutral-700 bg-neutral-900 py-2 text-center text-sm text-neutral-200 transition hover:border-rose-500 hover:text-rose-300"
                >
                  {episode.episodeNo}
                </Link>
              ))}
            </div>
          </section>
        </div>
      )}
    </main>
  )
}

import { useEffect, useMemo, useState } from 'react'
import { Link, useParams, useSearchParams } from 'react-router-dom'
import { getApiErrorMessage } from '../api/client'
import { formatLikes, getDrama, type DramaDetail } from '../api/dramas'
import { useDramaInteractions } from '../hooks/useDramaInteractions'

type LoadState = 'loading' | 'ready' | 'error'

export default function PlayerPage() {
  const { id } = useParams()
  const [searchParams, setSearchParams] = useSearchParams()
  const [detail, setDetail] = useState<DramaDetail | null>(null)
  const [state, setState] = useState<LoadState>('loading')
  const [error, setError] = useState('')
  const { like, favorite, hint } = useDramaInteractions()

  useEffect(() => {
    if (!id) {
      return
    }
    let cancelled = false
    setState('loading')
    getDrama(id)
      .then((data) => {
        if (cancelled) return
        setDetail(data)
        setState('ready')
      })
      .catch((err) => {
        if (cancelled) return
        setError(getApiErrorMessage(err))
        setState('error')
      })
    return () => {
      cancelled = true
    }
  }, [id])

  const episodes = useMemo(() => detail?.episodes ?? [], [detail])
  // ?ep= 定位当前集：缺失/非法时回落第 1 集
  const epParam = Number(searchParams.get('ep'))
  const current = episodes.find((episode) => episode.episodeNo === epParam) ?? episodes[0]

  const selectEpisode = (episodeNo: number) => {
    setSearchParams({ ep: String(episodeNo) })
  }

  if (state === 'loading') {
    return (
      <main className="flex flex-1 items-center justify-center">
        <p className="text-sm text-neutral-400">加载中…</p>
      </main>
    )
  }

  if (state === 'error' || !detail || !current) {
    return (
      <main className="flex flex-1 flex-col items-center justify-center gap-3">
        <p className="text-sm text-red-400">{state === 'error' ? error : '暂无剧集'}</p>
        <Link
          to="/"
          className="rounded-lg border border-neutral-700 px-4 py-1.5 text-sm text-neutral-300 transition hover:border-neutral-500 hover:text-white"
        >
          回首页
        </Link>
      </main>
    )
  }

  return (
    <main className="flex w-full flex-1 flex-col items-center gap-5 md:flex-row md:items-start md:justify-center md:gap-8 md:px-4 md:py-6">
      {/* 竖屏播放区：宽 min(100vw, 400px)，容器 9:16，视频 object-contain 不拉宽不裁切 */}
      <div className="w-full max-w-[400px] md:w-[400px]">
        <div className="aspect-[9/16] max-h-[calc(100dvh-9rem)] w-full overflow-hidden bg-black md:rounded-xl">
          {/* key 随集切换强制重载 video 元素 */}
          <video
            key={current.id}
            src={current.videoUrl}
            controls
            autoPlay
            playsInline
            className="h-full w-full object-contain"
          />
        </div>
        <p className="mt-2 px-4 text-center text-sm text-neutral-300 md:px-0">
          {current.title} · {current.durationSec}s
        </p>
      </div>

      {/* 信息栏：平板/PC 右栏，手机在视频下方 */}
      <aside className="w-full max-w-[400px] px-4 pb-8 md:w-80 md:shrink-0 md:px-0 md:pb-0">
        <h1 className="text-lg font-bold">{detail.title}</h1>
        <div className="mt-1.5 flex flex-wrap items-center gap-2 text-sm text-neutral-400">
          <span className="rounded-full bg-rose-500/15 px-2 py-0.5 text-rose-400">{detail.category}</span>
          <span>全 {detail.episodeCount} 集</span>
          <span className="text-rose-300">♥ {formatLikes(detail.likeCount)}</span>
        </div>

        <div className="mt-3 flex items-center gap-2.5">
          <button
            onClick={like}
            className={
              detail.liked
                ? 'rounded-lg bg-rose-500 px-4 py-1.5 text-sm font-medium text-white transition hover:bg-rose-600'
                : 'rounded-lg border border-neutral-700 px-4 py-1.5 text-sm text-neutral-200 transition hover:border-rose-500 hover:text-rose-300'
            }
          >
            ♥ {detail.liked ? '已赞' : '点赞'}
          </button>
          <button
            onClick={favorite}
            className={
              detail.favorited
                ? 'rounded-lg bg-amber-500 px-4 py-1.5 text-sm font-medium text-white transition hover:bg-amber-600'
                : 'rounded-lg border border-neutral-700 px-4 py-1.5 text-sm text-neutral-200 transition hover:border-amber-500 hover:text-amber-300'
            }
          >
            ★ {detail.favorited ? '已收藏' : '收藏'}
          </button>
        </div>
        {hint && <p className="mt-2 text-sm text-neutral-400">{hint}</p>}

        <p className="mt-3 text-sm leading-6 text-neutral-300">{detail.description}</p>

        <h2 className="mt-5 text-sm font-semibold">选集</h2>
        <div className="mt-2.5 grid grid-cols-6 gap-2">
          {detail.episodes.map((episode) => (
            <button
              key={episode.id}
              onClick={() => selectEpisode(episode.episodeNo)}
              className={
                episode.episodeNo === current.episodeNo
                  ? 'rounded-lg bg-rose-500 py-1.5 text-sm font-medium text-white'
                  : 'rounded-lg border border-neutral-700 bg-neutral-900 py-1.5 text-sm text-neutral-200 transition hover:border-rose-500 hover:text-rose-300'
              }
            >
              {episode.episodeNo}
            </button>
          ))}
        </div>

        <Link to={`/drama/${detail.id}`} className="mt-5 inline-block text-sm text-neutral-400 transition hover:text-white">
          ← 返回详情
        </Link>
      </aside>
    </main>
  )
}

import { useState, type FormEvent } from 'react'
import { Link, useNavigate, useSearchParams } from 'react-router-dom'
import { login as loginApi } from '../api/auth'
import { getApiErrorMessage } from '../api/client'
import { useAuth } from '../store/AuthContext'

export default function LoginPage() {
  const [username, setUsername] = useState('')
  const [password, setPassword] = useState('')
  const [error, setError] = useState('')
  const [loading, setLoading] = useState(false)
  const { login } = useAuth()
  const navigate = useNavigate()
  const [searchParams] = useSearchParams()
  const from = searchParams.get('from') || '/'

  const submit = async (event: FormEvent) => {
    event.preventDefault()
    if (!username.trim() || !password) {
      setError('请输入用户名和密码')
      return
    }
    setLoading(true)
    setError('')
    try {
      const { token, user } = await loginApi(username.trim(), password)
      login(token, user)
      navigate(from, { replace: true })
    } catch (err) {
      setError(getApiErrorMessage(err))
    } finally {
      setLoading(false)
    }
  }

  return (
    <main className="mx-auto w-full max-w-sm px-4 py-10">
      <h1 className="text-2xl font-bold">登录</h1>
      <p className="mt-1 text-sm text-neutral-400">登录后可点赞、收藏短剧</p>

      <form onSubmit={submit} className="mt-6 space-y-4">
        <div>
          <label htmlFor="login-username" className="mb-1 block text-sm text-neutral-300">
            用户名
          </label>
          <input
            id="login-username"
            value={username}
            onChange={(e) => setUsername(e.target.value)}
            placeholder="请输入用户名"
            autoComplete="username"
            className="w-full rounded-lg border border-neutral-700 bg-neutral-900 px-3 py-2 outline-none transition focus:border-rose-500"
          />
        </div>
        <div>
          <label htmlFor="login-password" className="mb-1 block text-sm text-neutral-300">
            密码
          </label>
          <input
            id="login-password"
            type="password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            placeholder="请输入密码"
            autoComplete="current-password"
            className="w-full rounded-lg border border-neutral-700 bg-neutral-900 px-3 py-2 outline-none transition focus:border-rose-500"
          />
        </div>
        {error && <p className="text-sm text-red-400">{error}</p>}
        <button
          type="submit"
          disabled={loading}
          className="w-full rounded-lg bg-rose-500 py-2.5 font-medium text-white transition hover:bg-rose-600 disabled:opacity-50"
        >
          {loading ? '登录中…' : '登录'}
        </button>
      </form>

      <div className="mt-4 flex flex-wrap items-center gap-2 text-sm text-neutral-400">
        <span>演示账号快捷填充：</span>
        <button
          type="button"
          onClick={() => {
            setUsername('demo')
            setPassword('demo123')
          }}
          className="rounded-md border border-neutral-700 px-2 py-0.5 transition hover:text-white"
        >
          demo / demo123
        </button>
        <button
          type="button"
          onClick={() => {
            setUsername('admin')
            setPassword('admin123')
          }}
          className="rounded-md border border-neutral-700 px-2 py-0.5 transition hover:text-white"
        >
          admin / admin123
        </button>
      </div>

      <p className="mt-6 text-sm text-neutral-400">
        还没有账号？
        <Link to="/register" className="ml-1 text-rose-400 transition hover:text-rose-300">
          去注册
        </Link>
      </p>
    </main>
  )
}

import { useState, type FormEvent } from 'react'
import { Link, useNavigate } from 'react-router-dom'
import { register as registerApi } from '../api/auth'
import { getApiErrorMessage } from '../api/client'
import { useAuth } from '../store/AuthContext'

export default function RegisterPage() {
  const [username, setUsername] = useState('')
  const [password, setPassword] = useState('')
  const [confirm, setConfirm] = useState('')
  const [error, setError] = useState('')
  const [loading, setLoading] = useState(false)
  const { login } = useAuth()
  const navigate = useNavigate()

  const submit = async (event: FormEvent) => {
    event.preventDefault()
    const name = username.trim()
    if (name.length < 2 || name.length > 50) {
      setError('用户名长度须在 2~50 之间')
      return
    }
    if (!password) {
      setError('请输入密码')
      return
    }
    if (password !== confirm) {
      setError('两次输入的密码不一致')
      return
    }
    setLoading(true)
    setError('')
    try {
      // 注册即登录：成功直接进入登录态并回首页
      const { token, user } = await registerApi(name, password)
      login(token, user)
      navigate('/', { replace: true })
    } catch (err) {
      setError(getApiErrorMessage(err))
    } finally {
      setLoading(false)
    }
  }

  return (
    <main className="mx-auto w-full max-w-sm px-4 py-10">
      <h1 className="text-2xl font-bold">注册</h1>
      <p className="mt-1 text-sm text-neutral-400">注册即登录，马上开始追剧</p>

      <form onSubmit={submit} className="mt-6 space-y-4">
        <div>
          <label htmlFor="reg-username" className="mb-1 block text-sm text-neutral-300">
            用户名
          </label>
          <input
            id="reg-username"
            value={username}
            onChange={(e) => setUsername(e.target.value)}
            placeholder="2~50 个字符"
            autoComplete="username"
            className="w-full rounded-lg border border-neutral-700 bg-neutral-900 px-3 py-2 outline-none transition focus:border-rose-500"
          />
        </div>
        <div>
          <label htmlFor="reg-password" className="mb-1 block text-sm text-neutral-300">
            密码
          </label>
          <input
            id="reg-password"
            type="password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            placeholder="请输入密码"
            autoComplete="new-password"
            className="w-full rounded-lg border border-neutral-700 bg-neutral-900 px-3 py-2 outline-none transition focus:border-rose-500"
          />
        </div>
        <div>
          <label htmlFor="reg-confirm" className="mb-1 block text-sm text-neutral-300">
            确认密码
          </label>
          <input
            id="reg-confirm"
            type="password"
            value={confirm}
            onChange={(e) => setConfirm(e.target.value)}
            placeholder="再输入一次密码"
            autoComplete="new-password"
            className="w-full rounded-lg border border-neutral-700 bg-neutral-900 px-3 py-2 outline-none transition focus:border-rose-500"
          />
        </div>
        {error && <p className="text-sm text-red-400">{error}</p>}
        <button
          type="submit"
          disabled={loading}
          className="w-full rounded-lg bg-rose-500 py-2.5 font-medium text-white transition hover:bg-rose-600 disabled:opacity-50"
        >
          {loading ? '注册中…' : '注册'}
        </button>
      </form>

      <p className="mt-6 text-sm text-neutral-400">
        已有账号？
        <Link to="/login" className="ml-1 text-rose-400 transition hover:text-rose-300">
          去登录
        </Link>
      </p>
    </main>
  )
}

